import { Transition } from 'motion-dom';

type Direction = "up" | "down" | "left" | "right";
/**
 * Whether the reveal continues in the cover's direction of travel
 * (`"normal"` — a sweep-through) or retreats back the way it came
 * (`"reverse"` — a door that opens and closes).
 */
type DirectionMode = "normal" | "reverse";
/**
 * The spatial sequence in which a grid of tiles activates. `stagger()`
 * then resolves the per-tile delay along this sequence.
 */
type TileOrder = "rows" | "columns" | "diagonal" | "radial" | "random";
/**
 * The minimal animation surface curtains needs to await and abort a phase.
 * Satisfied by Motion's mini `animate` controls and our `combine` helper.
 */
interface CurtainAnimation {
    finished: Promise<unknown>;
    stop: () => void;
}
/** The measured size of the overlay's container, used to size effects. */
interface BoxSize {
    width: number;
    height: number;
}
interface CurtainEffect {
    /**
     * Build the overlay DOM inside the container and keep a handle to whatever
     * `cover`/`reveal` animate. `box` is the container's measured size —
     * effects must size from it (not `window`) so they work when scoped to an
     * element.
     */
    setup: (container: HTMLElement, box?: BoxSize) => void;
    /** Animate the overlay in until it fully occludes the viewport. */
    cover: (transition?: Transition) => CurtainAnimation;
    /** Animate the overlay back out to reveal the freshly swapped content. */
    reveal: (transition?: Transition) => CurtainAnimation;
}
type CurtainEffectFactory = () => CurtainEffect;
/**
 * The DOM-mutating callback run while the page is fully covered — swap
 * content, change route, await fonts/data. Resolves before the reveal.
 */
type CurtainsCallback = () => void | Promise<void>;
/**
 * A value applied to both phases, or a `[cover, reveal]` tuple that sets each
 * phase independently — the same shape as the directional `direction` option.
 */
type Pair<T> = T | [T, T];
interface CurtainsOptions {
    /**
     * The transition effect. Pass a configured effect (`wipe({ ... })`) or the
     * factory itself (`wipe`) to use its defaults. A `[in, out]` tuple mixes a
     * different effect for the reveal — e.g. `[wipe({ direction: "left" }),
     * iris()]`. Defaults to `fade`.
     */
    effect?: Pair<CurtainEffect | CurtainEffectFactory>;
    /**
     * Animation timing. A single `Transition` times both phases; a `[cover,
     * reveal]` tuple times each independently. When an effect animates multiple
     * elements, `delay: stagger()` resolves per element in turn.
     */
    transition?: Pair<Transition>;
    /**
     * Scope the transition to a single element instead of the whole viewport.
     * The overlay mounts inside it (so it follows scroll and tracks the box
     * via `inset: 0`) rather than the top layer. The element must establish a
     * containing block — i.e. be positioned (`relative`/`absolute`/etc.).
     */
    scope?: HTMLElement;
}
/** Shared options consumed by direction-aware effects. */
interface DirectionalOptions {
    direction?: Direction | [Direction, Direction];
    directionMode?: DirectionMode;
}

/** A solid panel that fades in, hides the swap, then fades back out. */
declare function fade(): CurtainEffect;

interface WipeOptions extends DirectionalOptions {
    /** Tilt of the wipe edge, in degrees (0 = straight). */
    angle?: number;
}
/**
 * A solid panel that sweeps across the viewport. With an `angle` the leading
 * edge is skewed — the panel is oversized by *exactly* the skew shear and
 * centred, so it travels precisely one panel-width with no wasted (invisible)
 * travel. By default the reveal continues in the cover's direction; `direction
 * Mode: "reverse"` makes it retreat like a closing door.
 */
declare function wipe(options?: WipeOptions): CurtainEffect;

interface ClipWipeOptions extends DirectionalOptions {
    /** Tilt of the wipe edge, in degrees (0 = straight). */
    angle?: number;
    /**
     * Bow the leading edge into a convex curve that pulls out ahead in the
     * middle, as a fraction of the box along the travel axis (0 = straight,
     * ~0.15 = a gentle arc). Takes precedence over `angle`.
     */
    bow?: number;
}
/**
 * A wipe whose edge is a clip on a *static* overlay — the element never moves,
 * so it's ideal for revealing fixed content (an image, gradient, poster).
 * Supports any direction, `directionMode`, and an exact `angle` (no oversize,
 * no wasted travel) via a slanted polygon edge.
 */
declare function clipWipe(options?: ClipWipeOptions): CurtainEffect;

interface IrisOptions {
    /**
     * Where the circle grows from. Numbers are 0–1 fractions of the box (like
     * Motion's `originX`/`originY`), so the default `{ x: 0.5, y: 0.5 }` is the
     * centre and a click-origin wipe is `{ x: clientX / innerWidth, ... }`.
     * Strings pass through as CSS lengths, e.g. `{ x: "100px", y: "50%" }`.
     */
    origin?: {
        x: number | string;
        y: number | string;
    };
}
/** A circular clip that expands to cover, then contracts to reveal. */
declare function iris(options?: IrisOptions): CurtainEffect;

interface DoorsOptions {
    /** Which axis the doors close along. Horizontal values → left/right
     *  doors; vertical values → top/bottom doors. Defaults to horizontal. */
    direction?: Direction;
}
/** Two panels that meet in the middle to cover, then part to reveal. */
declare function doors(options?: DoorsOptions): CurtainEffect;

/** A tile dimension: a px `number`, a `"50%"` fraction of the box axis it
 *  tiles, or a `"100px"`-style length string. */
type TileSize = number | string;

interface PixelsOptions {
    /** Tile edge length: px (`100`), a `"50%"` fraction of the box, or
     *  `[width, height]` for rectangular tiles. */
    size?: TileSize | [TileSize, TileSize];
    /** Activation sequence the stagger walks. Ignored when `direction` is set. */
    order?: TileOrder;
    /**
     * Sweep the fill across the grid as a directional wavefront, angled in
     * degrees like `wipe`: 0 = → (right), 90 = ↓ (down), 180 = ← (left), 270 =
     * ↑ (up). Tiles sharing the wavefront flip together (a 90° sweep flips a
     * whole row at once), so the edge reads as a hard line. Takes precedence
     * over `order`. Soften the edge with `noise`.
     */
    direction?: number;
    /**
     * Softens a `direction` sweep's leading edge, 0–1. `0` keeps a hard,
     * straight wavefront; higher values jitter each tile's timing so the edge
     * dithers into a soft band; `1` is fully random (like `order: "random"`).
     */
    noise?: number;
    /** Whether the reveal replays the order/sweep or runs it in reverse. */
    directionMode?: DirectionMode;
}
/** A grid of tiles that fill in to cover, then clear out to reveal. */
declare function pixels(options?: PixelsOptions): CurtainEffect;

interface BlindsOptions {
    /** Slat thickness in px. */
    size?: number;
    /** Slat layout: `"row"` → horizontal slats; `"column"` → vertical slats. */
    direction?: "row" | "column";
    directionMode?: DirectionMode;
}
/**
 * Venetian-blind slats that scale shut to cover, then open to reveal. Each
 * slat scales along its own stacking axis (so the slats thin out). The reveal
 * flips each slat's origin so they continue past rather than spring back.
 */
declare function blinds(options?: BlindsOptions): CurtainEffect;

interface ShutterOptions {
    /** Column width in px. */
    size?: number;
}
/** Interleaved columns that slide in from alternating top and bottom. */
declare function shutter(options?: ShutterOptions): CurtainEffect;

interface StaggerWipeOptions {
    /** Strip thickness in px. */
    size?: number;
    /** The direction the wipe travels. Defaults to `"down"`. */
    direction?: Direction;
    directionMode?: DirectionMode;
}
/**
 * Strips that each wipe in `direction`, staggered across the perpendicular
 * axis — a cascading wipe. The reveal continues in the cover's direction
 * rather than springing back.
 */
declare function staggerWipe(options?: StaggerWipeOptions): CurtainEffect;

/**
 * Run a page transition between two views, stage-curtain style: cover the
 * viewport, run `callback` to swap content while it's hidden, then reveal.
 *
 * ```ts
 * await curtains(
 *     async () => {
 *         await downloadFonts()
 *         updateDOM()
 *     },
 *     { effect: wipe({ direction: "left" }), transition: { duration: 0.2 } }
 * )
 * ```
 *
 * Pass a `[in, out]` tuple to `effect` (and optionally `transition`) to mix a
 * different effect or timing for the reveal:
 *
 * ```ts
 * await curtains(updateDOM, {
 *     effect: [wipe({ direction: "left" }), iris()],
 *     transition: [{ duration: 0.3 }, { duration: 0.5 }],
 * })
 * ```
 *
 * The promise resolves once the reveal completes. Respects
 * `prefers-reduced-motion` by swapping with no transition.
 */
declare function curtains(callback: CurtainsCallback, options?: CurtainsOptions): Promise<void>;

export { blinds, clipWipe, curtains, doors, fade, iris, pixels, shutter, staggerWipe, wipe };
export type { BlindsOptions, BoxSize, ClipWipeOptions, CurtainAnimation, CurtainEffect, CurtainEffectFactory, CurtainsCallback, CurtainsOptions, Direction, DirectionMode, DirectionalOptions, DoorsOptions, IrisOptions, Pair, PixelsOptions, ShutterOptions, StaggerWipeOptions, TileOrder, WipeOptions };
